# nombres que puede elegir el personal para una categoria
CAT_ICONS = [('leaf', 'Hoja'), ('cup', 'Té / infusión'), ('pill', 'Suplemento'), ('bottle', 'Cuidado personal'),
             ('wheat', 'Granos'), ('sprout', 'Semillas'), ('droplet', 'Aceite'), ('gift', 'Regalo'), ('award', 'Premium')]


def icon(name, size=20, cls=''):
    body = P.get(name) or P['leaf']
    return Markup(
        f'<svg class="ic {cls}" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
        f'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{body}</svg>')
